<#
    Builds the OrbixPOS Windows release zip. MAINTAINER TOOL - never shipped to a client.

      .\dist\build-pos.ps1               # test, build, zip (notes from pos_app\release\notes\)
      .\dist\build-pos.ps1 -SkipTests    # skip `flutter test` (not for a release)
      .\dist\build-pos.ps1 -Force        # overwrite an existing zip of this version
      .\dist\build-pos.ps1 -Notes x.txt  # use another notes file (e.g. a throwaway test build)

    Steps: read the version from pos_app\pubspec.yaml, run `flutter test`, run
    `flutter build windows --release`, check pos_app.exe is there and carries that version, then
    zip the Release folder with the documents below into dist\OrbixPOS-<version>-windows.zip and
    print its SHA-256.

    One version, one zip. Every materially different build gets a NEW version. To release:
      1. bump `version:` in pos_app\pubspec.yaml (e.g. 1.5.2+10 -> 1.5.3+11);
      2. write pos_app\release\notes\<version>.md - what changed, for the shop, plain ASCII,
         Markdown body only (no heading: the script adds "OrbixPOS <version>");
      3. if the cashier-facing behaviour changed, update docs\pos-user-manual\ and rebuild the
         manual (bash docs/tools/build-pos-manual.sh) so docs\POS-USER-MANUAL.docx is current;
      4. commit, then run this script.
    It refuses to overwrite an existing zip of the same version unless -Force, so two different
    builds can never be told apart only by their date.

    What goes in the zip besides the app (every document as .md AND .txt):
      README.md / .txt                    pos_app\release\README.md (install / setup / HTTPS /
                                          upgrade / troubleshooting guide) with the version,
                                          build commit and this version's notes filled in
      Docs\RELEASE-NOTES.md / .txt        every pos_app\release\notes\*.md, newest first
      Docs\OrbixPOS-User-Manual.docx      docs\POS-USER-MANUAL.docx
      Docs\OrbixPOS-User-Manual.md / .txt docs\POS-USER-MANUAL.md
    Markdown is the only source. The .txt copies are generated by dist\md2txt.js - the same
    converter the ERP release uses (ASCII, CRLF, wrapped for Notepad) - with local node, or
    in a node:20-alpine container when node is not installed.

    It warns if the working tree has uncommitted changes: they are built into the zip, and the
    README then reads "<commit>+uncommitted" so the build is never mistaken for a clean one.

    Never builds with POS_ALLOW_INSECURE_TLS: a till shipped with it accepts any certificate.

    Requirements: Flutter (Windows desktop toolchain), git.
#>

[CmdletBinding()]
param(
    # This version's notes. Default: pos_app\release\notes\<version>.txt (required for a release).
    [string] $Notes,
    # Skip `flutter test`. For a quick local build only - never for a release.
    [switch] $SkipTests,
    # Overwrite dist\OrbixPOS-<version>-windows.zip if it already exists.
    [switch] $Force
)

$ErrorActionPreference = 'Stop'

$ScriptDir  = Split-Path -Parent $MyInvocation.MyCommand.Path
$RepoRoot   = Split-Path -Parent $ScriptDir
$PosDir     = Join-Path $RepoRoot 'pos_app'
$Pubspec    = Join-Path $PosDir 'pubspec.yaml'
$ReleaseDir = Join-Path $PosDir 'build\windows\x64\runner\Release'
$ReadMeTpl  = Join-Path $PosDir 'release\README.md'
$NotesDir   = Join-Path $PosDir 'release\notes'
$Manual     = Join-Path $RepoRoot 'docs\POS-USER-MANUAL.docx'
$ManualMd   = Join-Path $RepoRoot 'docs\POS-USER-MANUAL.md'
$Md2Txt     = Join-Path $ScriptDir 'md2txt.js'

function Write-Step { param([string]$m) Write-Host ''; Write-Host "==> $m" -ForegroundColor White }
function Write-Ok   { param([string]$m) Write-Host "  ok  $m" -ForegroundColor Green }
function Write-Warn { param([string]$m) Write-Host "  !!  $m" -ForegroundColor Yellow }
function Stop-WithError {
    param([string]$m)
    Write-Host ''; Write-Host 'ERROR' -ForegroundColor Red; Write-Host ''; Write-Host $m; Write-Host ''
    exit 1
}

# Run a native command in a directory; fail the build on a non-zero exit code.
function Invoke-In {
    param([string]$Dir, [string]$What, [scriptblock]$Command)
    Push-Location $Dir
    try {
        & $Command
        if ($LASTEXITCODE -ne 0) { Stop-WithError "$What failed (exit code $LASTEXITCODE). See the output above." }
    } finally { Pop-Location }
}

# ---------------------------------------------------------------------------
Write-Step 'Checking tools'
foreach ($tool in 'flutter', 'git') {
    if ($null -eq (Get-Command $tool -ErrorAction SilentlyContinue)) { Stop-WithError "$tool is not installed or not on PATH." }
}
Write-Ok 'flutter, git found'

$VersionLine = Select-String -Path $Pubspec -Pattern '^version:\s*(\S+)' | Select-Object -First 1
if ($null -eq $VersionLine) { Stop-WithError "No 'version:' line found in $Pubspec." }
$Version = $VersionLine.Matches[0].Groups[1].Value
$BuildName = ($Version -split '\+')[0]      # 1.5.3+11 -> 1.5.3 (what the exe is stamped with)
$ZipPath = Join-Path $ScriptDir "OrbixPOS-$Version-windows.zip"
Write-Ok "version $Version"

if ((Test-Path $ZipPath) -and -not $Force) {
    Stop-WithError ("$ZipPath already exists.`n`n" +
        "Bump 'version:' in pos_app\pubspec.yaml for a new build, or pass -Force to replace it.")
}

# Plain ASCII only: the documents are opened in Notepad on whatever code page the till has, and
# a curly quote or a dash there turns into garbage.
function Read-AsciiText {
    param([string]$Path)
    $text = [IO.File]::ReadAllText($Path)
    if ($text -match '[^\x00-\x7F]') {
        Stop-WithError "$Path contains non-ASCII characters (e.g. curly quotes or long dashes). Use plain ASCII."
    }
    return $text
}

# Markdown -> .txt for every *.md in a directory, with the shared converter.
function Invoke-Md2Txt {
    param([string]$Dir)
    if ($null -ne (Get-Command node -ErrorAction SilentlyContinue)) {
        & node $Md2Txt $Dir | Out-Host
        return $LASTEXITCODE
    }
    if ($null -eq (Get-Command docker -ErrorAction SilentlyContinue)) {
        Stop-WithError 'Generating the .txt documents needs node or docker on PATH.'
    }
    $helper = Join-Path $Dir '.md2txt.js'
    Copy-Item $Md2Txt $helper -Force
    & docker run --rm -v "$($Dir -replace '\\','/'):/docs" node:20-alpine node /docs/.md2txt.js /docs | Out-Host
    $code = $LASTEXITCODE
    Remove-Item $helper -Force -ErrorAction SilentlyContinue
    return $code
}

$Utf8 = New-Object System.Text.UTF8Encoding($false)

if (-not (Test-Path $Md2Txt)) { Stop-WithError "Converter not found: $Md2Txt" }

if (-not $Notes) { $Notes = Join-Path $NotesDir "$Version.md" }
if (-not (Test-Path $Notes)) {
    Stop-WithError ("No release notes for $Version.`n`n" +
        "Write $(Join-Path $NotesDir "$Version.md") - what changed in this version, for the shop -`n" +
        "or pass -Notes <file> for a throwaway test build.")
}
$NotesText = (Read-AsciiText $Notes).Trim()
if (-not $NotesText) { Stop-WithError "$Notes is empty." }

if (-not (Test-Path $ReadMeTpl)) { Stop-WithError "README template not found: $ReadMeTpl" }
$ReadMeTemplate = Read-AsciiText $ReadMeTpl
foreach ($ph in '{{VERSION}}', '{{BUILD}}', '{{NOTES}}') {
    if (-not $ReadMeTemplate.Contains($ph)) { Stop-WithError "$ReadMeTpl is missing the $ph placeholder." }
}

# Every notes file, newest build number first (the part after '+' always increases).
$AllNotes = @(Get-ChildItem $NotesDir -Filter '*.md' | ForEach-Object {
    if ($_.BaseName -notmatch '^(\d+\.\d+\.\d+)\+(\d+)$') {
        Stop-WithError "$($_.FullName): notes files must be named <version>.md, e.g. 1.5.3+11.md."
    }
    [pscustomobject]@{
        Build   = [int]$Matches[2]
        Heading = "OrbixPOS $($Matches[1]) (build $($Matches[2]))"
        Text    = (Read-AsciiText $_.FullName).Trim()
    }
} | Sort-Object Build -Descending)

foreach ($m in $Manual, $ManualMd) {
    if (-not (Test-Path $m)) { Stop-WithError "User manual not found: $m (rebuild it: bash docs/tools/build-pos-manual.sh)." }
}
Write-Ok "notes $(Split-Path -Leaf $Notes), $($AllNotes.Count) version(s) in the release notes, manual found"

Push-Location $RepoRoot
try {
    $Branch = (& git rev-parse --abbrev-ref HEAD | Select-Object -First 1).Trim()
    $Commit = (& git rev-parse --short HEAD | Select-Object -First 1).Trim()
    $Dirty  = @(& git status --porcelain --untracked-files=no -- pos_app)
} finally { Pop-Location }
Write-Ok "building $Branch @ $Commit"
if ($Dirty.Count -gt 0) {
    # Allowed (the version bump itself is usually uncommitted), but the build is then not exactly $Commit.
    Write-Warn "pos_app has $($Dirty.Count) uncommitted change(s) - they WILL be in this build"
    $Commit = "$Commit+uncommitted"
}

# ---------------------------------------------------------------------------
Write-Step 'Fetching packages'
Invoke-In $PosDir 'flutter pub get' { & flutter pub get }
Write-Ok 'packages ready'

if ($SkipTests) {
    Write-Warn 'tests skipped (-SkipTests) - do not ship this build'
} else {
    Write-Step 'Running the POS tests'
    Invoke-In $PosDir 'flutter test' { & flutter test }
    Write-Ok 'tests passed'
}

Write-Step 'Building the Windows release'
# Clear the old output so a file the new build no longer produces cannot ride along into the zip.
if (Test-Path $ReleaseDir) { Remove-Item -Recurse -Force $ReleaseDir }
# Deliberately no --dart-define: POS_ALLOW_INSECURE_TLS must never be on in a shipped till.
Invoke-In $PosDir 'flutter build windows' { & flutter build windows --release }

$Exe = Join-Path $ReleaseDir 'pos_app.exe'
if (-not (Test-Path $Exe)) { Stop-WithError "The build produced no pos_app.exe under $ReleaseDir." }
$ExeVersion = (Get-Item $Exe).VersionInfo.ProductVersion
if ($ExeVersion -and -not $ExeVersion.StartsWith($BuildName)) {
    Stop-WithError "pos_app.exe is stamped '$ExeVersion', not $Version. Run 'flutter clean' in pos_app and try again."
}
Write-Ok "pos_app.exe built (version $ExeVersion)"

# ---------------------------------------------------------------------------
Write-Step 'Packaging the zip'
$Staging = Join-Path ([IO.Path]::GetTempPath()) "orbixpos-$Version-$(Get-Date -Format 'yyyyMMddHHmmss')"
New-Item -ItemType Directory -Force $Staging | Out-Null
try {
    Copy-Item -Recurse -Force (Join-Path $ReleaseDir '*') $Staging
    $DocsDir = Join-Path $Staging 'Docs'
    New-Item -ItemType Directory -Force $DocsDir | Out-Null

    $ReadMe = $ReadMeTemplate.Replace('{{VERSION}}', $Version)
    $ReadMe = $ReadMe.Replace('{{BUILD}}', "$Branch @ $Commit")
    $ReadMe = $ReadMe.Replace('{{NOTES}}', $NotesText)
    [IO.File]::WriteAllText((Join-Path $Staging 'README.md'), $ReadMe, $Utf8)

    $History = "# OrbixPOS release notes`n`n" +
        "Newest first. Installing or upgrading: see README.txt next to ``pos_app.exe``.`n`n" +
        (($AllNotes | ForEach-Object { "## $($_.Heading)`n`n$($_.Text)" }) -join "`n`n---`n`n") + "`n"
    [IO.File]::WriteAllText((Join-Path $DocsDir 'RELEASE-NOTES.md'), $History, $Utf8)

    Copy-Item -Force $Manual   (Join-Path $DocsDir 'OrbixPOS-User-Manual.docx')
    # The compiled manual opens with a maintainer line (repo name, stack, "generated from the
    # codebase") that assemble_docs.py writes for the repo copy. A shop has no use for it.
    $ManualText = [IO.File]::ReadAllText($ManualMd) -replace '(?m)^_ERPCLEAN2 .*_\r?\n\r?\n', ''
    [IO.File]::WriteAllText((Join-Path $DocsDir 'OrbixPOS-User-Manual.md'), $ManualText, $Utf8)

    # The .txt twins, from the Markdown just written - never hand-made, so they cannot drift.
    foreach ($d in $Staging, $DocsDir) {
        if ((Invoke-Md2Txt -Dir $d) -ne 0) { Stop-WithError "Could not generate the .txt documents in $d." }
    }
    foreach ($f in 'README.txt', 'Docs\RELEASE-NOTES.txt', 'Docs\OrbixPOS-User-Manual.txt') {
        if (-not (Test-Path (Join-Path $Staging $f))) { Stop-WithError "The converter did not produce $f." }
    }

    if (Test-Path $ZipPath) { Remove-Item -Force $ZipPath }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::CreateFromDirectory($Staging, $ZipPath)
} finally {
    Remove-Item -Recurse -Force $Staging -ErrorAction SilentlyContinue
}

$ZipItem = Get-Item $ZipPath
$Sha = (Get-FileHash -Algorithm SHA256 $ZipPath).Hash.ToLower()
Write-Ok ("{0} ({1:N1} MB)" -f $ZipItem.Name, ($ZipItem.Length / 1MB))
Write-Ok "SHA-256 $Sha"

Write-Host ''
Write-Host "Done. OrbixPOS $Version from $Branch @ $Commit" -ForegroundColor Green
Write-Host "Zip: $ZipPath"
Write-Host 'Before handing it over: unzip it on a clean folder, start pos_app.exe, and do a test sale + print.'
